import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.UpdateBlock{Position: protocol.BlockPos{1, -2, 3}, NewBlockRuntimeID: 300, Flags: 3, Layer: 1}
PLACED = bytes.fromhex("020306ac020301")

# generated by gophertunnel b8bd735:
# packet.UpdateBlock{Flags: 200}
WIDE_FLAGS = bytes.fromhex("00000000c80100")

GOLDENS = [
    pytest.param(
        v2225.UpdateBlockPacket(
            pos=v2225.BlockPos(x=1, y=-2, z=3),
            runtime_id=300,
            update_flags=3,
            layer=1,
        ),
        PLACED,
        id="placed",
    ),
    pytest.param(v2225.UpdateBlockPacket(update_flags=200), WIDE_FLAGS, id="wide-flags"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_update_block_is_packet_21(version):
    assert version.PACKETS[21] is version.UpdateBlockPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_block_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_block_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
